codeExample:
console.log("1. Script Start");

// Standard VIP (Microtask)
Promise.resolve().then(() => {
  console.log("4. Promise Resolved");
});

// Super VIP (nextTick Queue)
process.nextTick(() => {
  console.log("3. nextTick Executed! (Cut in front of the Promise!)");
});

// Macrotask (Timers Phase)
setTimeout(() => {
  console.log("5. setTimeout Executed");
}, 0);

console.log("2. Script End");

/*
Output:
1. Script Start
2. Script End
3. nextTick (Highest priority!)
4. Promise
5. setTimeout
*/
